            verdict: 'Axolotl wird über Konfigurationsdateien gesteuert, und genau das will man, sobald ein Trainingslauf über einen Cluster hinweg reproduzierbar sein muss statt aus einem Notebook rekonstruiert zu werden. Die README dokumentiert Multi-GPU über FSDP1, FSDP2 und DeepSpeed, Multi-Node über Torchrun und Ray sowie ND-Parallelität, die Context-, Tensor- und Fully-Sharded-Data-Parallelität sowohl innerhalb eines Knotens als auch über mehrere hinweg kombiniert. Expert Parallelism für verteiltes Mixture-of-Experts-Training ist ebenfalls vorhanden. Die Liste der Trainingsmethoden ist mit deutlichem Abstand die breiteste der drei: vollständiges Finetuning, LoRA, QLoRA, GPTQ, quantisierungsbewusstes Training, FP8-Mixed-Precision, Preference Tuning mit DPO, IPO, KTO und ORPO, Reinforcement Learning mit GRPO und GDPO sowie Reward- und Process-Reward-Modelling.',
