      regionalContext: {
        id: 'regional-context',
        title: 'Finetuning in der EU, in Japan und in China',
        content: 'Beim Finetuning laden Sie Ihre Trainingsdaten zu demjenigen hoch, der den Job ausführt. Damit wird die Entscheidung zwischen lokal und Cloud in drei wichtigen Märkten zu einer Frage der Datenkontrolle und nicht bloß zu einem Kostenvergleich.',
        subsections: [
          {
            title: 'Europäische Union',
            content: 'Ein Trainingsdatensatz aus Kundendaten, Support-Tickets oder internen Dokumenten ist personenbezogenes Datum im Sinne der DSGVO, und ihn an eine in den USA gehostete Finetuning-API zu senden, ist eine Übermittlung außerhalb der EU im Sinne der Artikel 44 bis 49, sofern Vertragsbedingungen und Infrastruktur des Anbieters nichts anderes vorsehen. Sie brauchen einen Auftragsverarbeitungsvertrag nach Artikel 28 mit der gewählten Plattform, und der Trainingsdatensatz lässt sich schwerer zurückholen als ein Inferenz-Prompt, weil er in die Gewichte eingeht. Das ist das stärkste Argument für lokales Finetuning in der EU: Mit Unsloth oder Axolotl auf eigener Hardware verlassen die Daten das Haus nie. Die französische CNIL weist mit ihrer Empfehlung lokaler KI für sensible Geschäftsdaten in dieselbe Richtung.',
          },
          {
            title: 'Japan',
            content: 'Japans Urheberrechtsrahmen war für maschinelles Lernen nach Artikel 30-4 historisch ungewöhnlich freizügig, was einer der Gründe dafür ist, dass die inländische Finetuning-Arbeit vergleichsweise aktiv ist. Die Einschränkung, die tatsächlich greift, ist Governance und nicht Urheberrecht: Das AI-Governance-Programm des METI drängt Unternehmen zu auditierbaren Datenwegen, und bei regulierter Arbeit heißt das, nachweisen zu können, welcher Datensatz welchen Checkpoint erzeugt hat. Lokales Training mit einem konfigurationsgesteuerten Framework hilft hier aus einem praktischen Grund, denn ein in die Versionsverwaltung eingecheckter Axolotl-YAML ist ein Prüfartefakt, wie es ein auf dem Laptop ausgeführtes Notebook nicht ist.',
          },
          {
            title: 'China',
            content: 'Unter dem Datensicherheitsgesetz (数据安全法) und den CAC-Regeln zur grenzüberschreitenden Übermittlung besteht das Compliance-Problem darin, ein proprietäres Trainingskorpus an eine ausländische Plattform zu senden, nicht im Finetuning selbst. Bereitstellungen für Teams auf dem chinesischen Festland verlangen in der Regel, dass das Training auf inländischer Infrastruktur gegen ein konformes Basismodell läuft, was keine dieser Cloud-Plattformen standardmäßig bietet. Lokales Finetuning gegen ein im Inland entwickeltes Open-Weight-Modell ist das praktikable Muster — siehe [lokale LLMs in China betreiben](/de/local-llms/deepseek-local-china-data-privacy-2026) zum Thema Datenresidenz.',
          },
        ],
        note: 'Stimmen Sie in jedem Markt lokal ab, in dem Sie angeben können müssen, wohin Ihre Trainingsdaten gegangen sind. Wo keine solche Einschränkung gilt, ist eine Cloud-API unproblematisch.',
      },
