      regionalContext: {
        id: 'regional-context',
        title: 'Fine-tuning en la UE, Japón y China',
        content: 'El fine-tuning sube sus datos de entrenamiento a quien ejecute el trabajo. Eso convierte la elección entre local y nube en una decisión de gobernanza de datos en tres mercados importantes, y no en una mera comparación de costes.',
        subsections: [
          {
            title: 'Unión Europea',
            content: 'Un conjunto de entrenamiento construido a partir de registros de clientes, tickets de soporte o documentos internos es dato personal bajo el RGPD, y enviarlo a una API de fine-tuning alojada en Estados Unidos constituye una transferencia fuera de la UE en el sentido de los artículos 44 a 49, salvo que los términos e infraestructura del proveedor indiquen otra cosa. Necesita un contrato de encargado de tratamiento del artículo 28 con la plataforma que elija, y el conjunto de entrenamiento es más difícil de revertir que un prompt de inferencia porque queda absorbido en los pesos. Este es el argumento más fuerte a favor del ajuste local en la UE: con Unsloth o Axolotl en hardware propio, los datos no salen nunca. La CNIL francesa ha apuntado en la misma dirección al recomendar IA local para datos empresariales sensibles.',
          },
          {
            title: 'Japón',
            content: 'El marco japonés de derechos de autor ha sido históricamente inusualmente permisivo con el aprendizaje automático en virtud del artículo 30-4, una de las razones por las que el trabajo nacional de fine-tuning ha sido comparativamente activo. La restricción que realmente aprieta es de gobernanza, no de derechos de autor: el programa de gobernanza de IA del METI empuja a las empresas hacia rutas de datos auditables, y en trabajo regulado eso significa poder demostrar qué conjunto de datos produjo qué punto de control. El entrenamiento local con un framework dirigido por configuración ayuda aquí por una razón práctica: un YAML de Axolotl versionado en el repositorio es un artefacto de auditoría como no lo es un cuaderno ejecutado en un portátil.',
          },
          {
            title: 'China',
            content: 'Bajo la Ley de Seguridad de Datos (数据安全法) y las normas de la CAC sobre transferencias transfronterizas, el problema de cumplimiento es enviar un corpus de entrenamiento propietario a una plataforma extranjera, no el fine-tuning en sí. Los despliegues que dan servicio a equipos de China continental suelen exigir que el entrenamiento se ejecute en infraestructura nacional contra un modelo base conforme, algo que ninguna de estas plataformas ofrece por defecto. El ajuste local contra un modelo de pesos abiertos desarrollado en el país es el patrón viable: véase [ejecutar LLM locales en China](/es/local-llms/deepseek-local-china-data-privacy-2026) para el panorama de residencia de datos.',
          },
        ],
        note: 'Ajuste en local en cualquier mercado donde deba poder declarar adónde fueron sus datos de entrenamiento. Una API en la nube está bien donde no exista tal restricción.',
      },
