            text: 'Ajuste localmente quando tiver uma GPU capaz e iterar com frequencia, e use uma API de fine-tuning na nuvem quando nao tiver hardware ou treinar tao pouco que a tarifa por job custe menos que o seu proprio tempo de configuracao.',
