        title: 'Pule isto se…',
        content: '**Se sua queixa e que o modelo nao conhece os documentos da sua empresa, o fine-tuning e a ferramenta errada e vai custar um ciclo de treino ate voce descobrir isso.** Esse e um problema de recuperacao. Uma pipeline RAG bem construida responde a partir de documentos que voce pode atualizar nesta tarde, ao passo que um ajuste os assa em pesos que voce teria de retreinar para corrigir.\n\nO fine-tuning se justifica quando voce precisa de um formato de saida consistente, um tom especifico ou uma habilidade estreita que o prompting nao produz de forma confiavel. Sao mudancas de comportamento, e comportamento e justamente o que o treino muda bem. Tente primeiro um prompt de sistema estruturado, depois recuperacao, e recorra a um treino apenas quando ambos falharem visivelmente naquilo de que voce precisa.',
