          '**Unsloth** — GitHubスター7.50万、Apache-2.0。READMEはマルチGPU構成、NVIDIA・AMD・IntelのGPU、CPU、Vulkanバックエンドへの対応を、Windows・Linux・WSL・macOS上で明記し、デスクトップ版も配布しています。オープンソース版でマルチGPUが有料の壁の向こうにあるわけでは**ありません**。',
