            content: '顧客記録、サポートチケット、社内文書から構成された学習データはGDPR上の個人データであり、それを米国でホストされるファインチューニングAPIへ送ることは、提供者の契約条件とインフラに別段の定めがない限り、第44条から第49条にいうEU域外移転にあたります。選定した基盤とは第28条に基づく処理者契約が必要で、学習データは重みに取り込まれるため推論プロンプトより取り消しが困難です。これはEUにおけるローカル調整の最も強い論拠です。自前のハードウェア上のUnslothやAxolotlなら、データは決して外に出ません。フランスのCNILも、機微な業務データにはローカルAIをという指針で同じ方向を示しています。',
