        content: '**اضبط محليًا إن كان لديك معالج رسومي قادر وتتوقع التكرار؛ واستخدم واجهة سحابية إن لم تكن تملك عتادًا، أو إن كنت تضبط النموذج بندرة تكفي لأن تكون الفوترة لكل مهمة أرخص من وقت الإعداد لديك.** يسبق هذا السؤال سؤال «أي إطار عمل»، لأنه يحدد أي نصف من هذه الصفحة يعنيك.\n\nوالصيغة الصادقة للمقايضة هي أن التدريب المحلي رخيص لكل تشغيل ومكلف لكل ساعة من انتباهك، بينما تعكس الواجهة السحابية هذه المعادلة. فمن يضبط نموذجًا مرة كل ربع سنة يكسب فعلًا حين لا يضطر إلى تتبّع تعارض في المشغّلات عند الحادية عشرة ليلًا. ومن يكرّر مرتين أسبوعيًا على المجموعة نفسها سيرى الفوترة بالرموز تتجاوز تكلفة العتاد سريعًا.',
