      regionalContext: {
        id: 'regional-context',
        title: 'الضبط الدقيق في الاتحاد الأوروبي واليابان والصين',
        content: 'يرفع الضبط الدقيق بيانات تدريبك إلى الجهة التي تنفّذ المهمة. وهذا يجعل الاختيار بين المحلي والسحابي قرار حوكمة بيانات في ثلاث أسواق كبرى، لا مجرد مقارنة تكاليف.',
        subsections: [
          {
            title: 'الاتحاد الأوروبي',
            content: 'مجموعة تدريب مبنية على سجلات عملاء أو تذاكر دعم أو مستندات داخلية تُعد بيانات شخصية بموجب اللائحة العامة لحماية البيانات، وإرسالها إلى واجهة ضبط مستضافة في الولايات المتحدة يشكّل نقلًا خارج الاتحاد بمفهوم المواد من 44 إلى 49، ما لم تنص شروط المزوّد وبنيته التحتية على خلاف ذلك. وتحتاج إلى عقد معالجة بموجب المادة 28 مع المنصة التي تختارها، كما أن مجموعة التدريب أصعب في التراجع عنها من موجّه استدلال لأنها تُستوعب داخل الأوزان. وهذه أقوى حجة لصالح الضبط المحلي في الاتحاد الأوروبي: فمع Unsloth أو Axolotl على عتادك الخاص، لا تغادر البيانات مكانها أبدًا. وقد أشارت الهيئة الفرنسية لحماية البيانات إلى الاتجاه نفسه بتوصيتها باستخدام ذكاء اصطناعي محلي للبيانات التجارية الحساسة.',
          },
          {
            title: 'اليابان',
            content: 'كان الإطار الياباني لحقوق المؤلف متساهلًا على نحو غير معتاد تاريخيًا مع تعلّم الآلة بموجب المادة 30-4، وهو أحد أسباب النشاط النسبي لأعمال الضبط المحلية هناك. غير أن القيد الذي يعضّ فعلًا هو الحوكمة لا حقوق المؤلف: إذ يدفع برنامج حوكمة الذكاء الاصطناعي التابع لوزارة الاقتصاد والتجارة والصناعة الشركات نحو مسارات بيانات قابلة للتدقيق، وفي الأعمال الخاضعة للتنظيم يعني ذلك القدرة على بيان أي مجموعة بيانات أنتجت أي نقطة تحقّق. والتدريب المحلي بإطار يُدار بالإعدادات يساعد هنا لسبب عملي، إذ إن ملف YAML لـAxolotl المودَع في نظام إدارة الإصدارات يمثّل أثرًا للتدقيق بما لا يمثّله دفتر ملاحظات شُغّل على حاسوب محمول.',
          },
          {
            title: 'الصين',
            content: 'بموجب قانون أمن البيانات (数据安全法) وقواعد إدارة الفضاء الإلكتروني بشأن النقل العابر للحدود، تكمن مشكلة الامتثال في إرسال مدونة تدريب مملوكة إلى منصة أجنبية، لا في الضبط الدقيق نفسه. وعمليات النشر التي تخدم فرقًا في البر الرئيسي تتطلب عادةً تشغيل التدريب على بنية تحتية محلية مقابل نموذج أساسي ممتثل، وهو ما لا تقدّمه أي من هذه المنصات السحابية افتراضيًا. والضبط المحلي مقابل نموذج مفتوح الأوزان مطوَّر محليًا هو النمط العملي — راجع [تشغيل النماذج اللغوية المحلية في الصين](/ar/local-llms/deepseek-local-china-data-privacy-2026) لصورة إقامة البيانات.',
          },
        ],
        note: 'اضبط محليًا في أي سوق يتعيّن فيه أن تكون قادرًا على بيان أين ذهبت بيانات تدريبك. أما الواجهة السحابية فتفي بالغرض حيث لا ينطبق قيد كهذا.',
      },
