        '**한 대를 넘어설 때 최적:** Axolotl — Torchrun과 Ray를 통한 멀티노드, ND 병렬, 가장 넓은 기법 범위',
        '**Apple Silicon에서 가장 가벼움:** MLX-LM — MIT 라이선스, 애플 MLX 위에 구축, mx.distributed로 분산 학습',
