        title: '이런 경우엔 건너뛰세요',
        content: '**불만이 모델이 회사 문서를 모른다는 것이라면 파인튜닝은 잘못된 도구이며, 그 사실을 알아내는 데 학습 주기 하나를 쓰게 됩니다.** 그것은 검색 문제입니다. 잘 만든 RAG 파이프라인은 오늘 오후에 갱신할 수 있는 문서를 바탕으로 답하지만, 파인튜닝은 그것을 가중치에 구워 넣어 고치려면 다시 학습해야 합니다.\n\n파인튜닝이 값을 하는 때는 일관된 출력 형식, 특정한 어조, 또는 프롬프트로는 안정적으로 얻지 못하는 좁은 기술이 필요할 때입니다. 이는 행동의 변화이고, 행동이야말로 학습이 잘 바꾸는 대상입니다. 먼저 구조화된 시스템 프롬프트를, 다음으로 검색을 시도하고, 필요한 바로 그 지점에서 둘 다 눈에 띄게 실패했을 때만 학습에 손을 대세요.',
